**`rename_photos.py`**

```python
#!/usr/bin/env python3
"""Rename photos to the date they were taken: 2024-05-12_001.jpg

Usage:
    python rename_photos.py                     # preview only (safe default)
    python rename_photos.py --apply             # actually rename
    python rename_photos.py ~/Pictures/Trip --apply
    python rename_photos.py --apply --recursive

Needs Pillow for EXIF:  pip install Pillow
"""

import argparse
import datetime as dt
import sys
from collections import defaultdict
from pathlib import Path

PHOTO_EXTS = {
    ".jpg", ".jpeg", ".png", ".tif", ".tiff", ".webp",
    ".heic", ".heif", ".dng", ".cr2", ".cr3", ".nef",
    ".arw", ".orf", ".raf", ".rw2",
}

# EXIF tags, in order of preference
EXIF_DATE_TAGS = (36867, 36868, 306)  # DateTimeOriginal, DateTimeDigitized, DateTime


def _clean(value) -> str:
    if isinstance(value, bytes):
        value = value.decode("ascii", "ignore")
    return str(value).strip().strip("\x00").strip()


def parse_datetime(value):
    """Parse an EXIF timestamp; return None if it looks bogus."""
    s = _clean(value)[:19]
    for fmt in ("%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            d = dt.datetime.strptime(s, fmt)
        except ValueError:
            continue
        # Reject unset dates ("0000:00:00 ...") and clock-reset dates.
        if 1970 <= d.year <= dt.datetime.now().year + 1:
            return d
    return None


def exif_datetime(path: Path):
    try:
        from PIL import Image
    except ImportError:
        return None
    try:
        with Image.open(path) as im:
            exif = im.getexif()
            if not exif:
                return None
            for tag in EXIF_DATE_TAGS:
                for container in (exif, _sub_ifd(exif)):
                    raw = container.get(tag) if container else None
                    if raw:
                        parsed = parse_datetime(raw)
                        if parsed:
                            return parsed
    except Exception:
        return None
    return None


def _sub_ifd(exif):
    try:
        return exif.get_ifd(0x8769)  # ExifIFD, where DateTimeOriginal lives
    except Exception:
        return None


def taken_datetime(path: Path):
    """Return (datetime, source_label)."""
    d = exif_datetime(path)
    if d:
        return d, "exif"
    try:
        return dt.datetime.fromtimestamp(path.stat().st_mtime), "mtime"
    except OSError:
        return None, "unreadable"


def collect(folder: Path, recursive: bool):
    it = folder.rglob("*") if recursive else folder.iterdir()
    out = []
    for p in it:
        if not p.is_file() or p.name.startswith("."):
            continue
        if p.suffix.lower() in PHOTO_EXTS:
            out.append(p)
    return sorted(out, key=lambda p: str(p).lower())


def build_plan(files):
    records = []
    for p in files:
        d, source = taken_datetime(p)
        records.append({"path": p, "dt": d, "source": source})

    by_date = defaultdict(list)
    for r in records:
        if r["dt"] is not None:
            by_date[r["dt"].date()].append(r)

    # Names already used in these folders, excluding the files we may rename.
    sources = {r["path"] for r in records}
    reserved = set()
    for r in records:
        reserved.update(r["path"].parent.glob("*"))
    reserved = {p for p in reserved if p not in sources}
    reserved = {p.with_name(p.name) for p in reserved}

    plan, skipped = [], []
    for day in sorted(by_date):
        items = sorted(by_date[day], key=lambda r: (r["dt"], r["path"].name.lower()))
        n = 0
        for r in items:
            while True:
                n += 1
                target = r["path"].with_name(f"{day.isoformat()}_{n:03d}{r['path'].suffix.lower()}")
                if target not in reserved:
                    break
            reserved.add(target)
            if target == r["path"]:
                skipped.append(r)
            else:
                plan.append((r, target))

    unreadable = [r for r in records if r["dt"] is None]
    return plan, skipped, unreadable, records


def apply_plan(plan):
    """Two-phase rename so a target can't clobber another source file."""
    staged, done = [], []
    try:
        for i, (rec, target) in enumerate(plan):
            src = rec["path"]
            tmp = src.with_name(f".__rename_tmp_{i}__{src.name}")
            src.rename(tmp)
            staged.append((tmp, target))
        for tmp, target in staged:
            tmp.rename(target)
            done.append(target)
    except OSError as exc:
        # Best effort: put anything still staged back where it came from.
        for tmp, _ in staged:
            try:
                if tmp.exists():
                    tmp.rename(tmp.name.split("__", 2)[-1] and
                               tmp.with_name(tmp.name.split("__", 2)[-1]))
            except OSError:
                pass
        raise SystemExit(f"error: rename failed: {exc}")
    return done


def main():
    ap = argparse.ArgumentParser(description="Rename photos by the date they were taken.")
    ap.add_argument("folder", nargs="?", default=".", type=Path)
    ap.add_argument("--apply", action="store_true", help="actually rename (default is a preview)")
    ap.add_argument("-r", "--recursive", action="store_true", help="include subfolders")
    args = ap.parse_args()

    folder = args.folder.expanduser().resolve()
    if not folder.is_dir():
        raise SystemExit(f"error: not a folder: {folder}")

    files = collect(folder, args.recursive)
    if not files:
        print(f"No photos found in {folder}")
        return

    plan, skipped, unreadable, records = build_plan(files)
    width = max((len(str(folder)) + 2, 20))

    print(f"Folder: {folder}")
    print(f"Photos found: {len(files)}   to rename: {len(plan)}   "
          f"unchanged: {len(skipped)}   unreadable: {len(unreadable)}\n")

    for rec, target in plan:
        flag = "" if rec["source"] == "exif" else "  (no EXIF, used file date)"
        print(f"  {rec['path'].name:<{width}} -> {target.name}{flag}")

    if unreadable:
        print("\nSkipped (no usable date):")
        for r in unreadable:
            print(f"  {r['path']}")

    if not args.apply:
        print(f"\nPreview only. Re-run with --apply to rename {len(plan)} file(s).")
        return

    try:
        done = apply_plan(plan)
    except SystemExit as exc:
        raise
    print(f"\nRenamed {len(done)} file(s).")


if __name__ == "__main__":
    main()
```

**How it behaves**

- Reads `DateTimeOriginal` from EXIF (falls back to `DateTimeDigitized`, then `DateTime`, then the file's modification date, flagged in the preview).
- Numbers photos per day in capture order: `2024-05-12_001.jpg`, `2024-05-12_002.jpg`, then restarts at `001` on the 13th.
- Previews by default; only changes anything with `--apply`.
- Renames in two phases, so a target name that happens to match another photo in the folder can't overwrite it.
- Skips hidden files and non-photos, and won't double-number files that are already named correctly.
- Lowercases extensions (`.JPG` → `.jpg`).

Try `python rename_photos.py` first to see the proposed names, then add `--apply` when it looks right.
